            stage = 1
        elif word == "LIMIT":
            if stage > 1:
                raise OntologyError(
                    "修饰符 LIMIT 重复出现或位置错误："
                    "必须位于 OFFSET 之前且至多一次"
                    f"（字符位置 {tok.pos}）"
                )
            self._advance()
            limit = self._parse_modifier_integer("LIMIT")
            stage = 2
        elif word == "OFFSET":
