        # ?y 全未绑定时保持投影字典序
        result = self.model.query(
            "SELECT ?x ?y WHERE { ?x knows ?z . OPTIONAL { ?x likes ?w } "
            "FILTER(!BOUND(?w)) } ORDER BY ?y"
        )
        self.assertEqual(
            result.rows,
            (("a", None), ("b", None), ("c", None), ("d", None)),
        )

    def test_order_by_with_star_projection(self):
