            "SELECT * WHERE { ?x knows ?y } ORDER BY DESC(?y) LIMIT 2"
        )
        self.assertEqual(result.variables, ("?x", "?y"))
        self.assertEqual(result.rows, (("a", "c"), ("c", "b")))

    def test_limit_truncates_after_sort(self):
