    def test_offset_skips_rows(self):
        result = self.model.query(
            "SELECT ?x WHERE { ?x knows ?y } ORDER BY ?x OFFSET 3"
        )
        self.assertEqual(result.rows, (("d",),))

    def test_limit_and_offset_together(self):
